import type { Profile } from '@ccx-public/component-types';
import Environment from '@identity/imslib/adobe-ims/environment/Environment';
import { IEnvironment } from '@identity/imslib/adobe-id/IEnvironment';
import { ImsApis } from '@identity/imslib/ims-apis/ImsApis';
import { ProfileService } from '@identity/imslib/profile/ProfileService';

export async function getProfileFromImslib(
    accessToken: string,
    clientId: string,
    environment: string,
): Promise<Profile> {
    const imsEnv = environment === 'stage' ? IEnvironment.STAGE : IEnvironment.PROD;
    Environment.loadEnvironment(imsEnv);
    const imsApis = new ImsApis();
    const profileService = new ProfileService({
        clientId,
        scope: '',
        imsApis,
    });
    return profileService.getProfile(accessToken);
}
